-- Transaction-only acceptance tests. No Auth/profile/content fixture survives rollback.
begin;
set constraints all immediate;
do $$
declare sa uuid:=gen_random_uuid(); adm uuid:=gen_random_uuid(); ed uuid:=gen_random_uuid(); ss uuid:=gen_random_uuid(); ads uuid:=gen_random_uuid(); es uuid:=gen_random_uuid();
 d public.cms_documents; master public.cms_documents; offer public.cms_documents; city public.cms_documents; payload jsonb; original jsonb; result jsonb; fixture uuid; design_doc public.cms_documents; checks int:=0; initial_versions int; media text:=gen_random_uuid()||'.png';
begin
 insert into auth.users(id,email,email_confirmed_at) values(sa,sa||'@macro3-test.invalid',now()),(adm,adm||'@macro3-test.invalid',now()),(ed,ed||'@macro3-test.invalid',now());
 insert into auth.sessions(id,user_id) values(ss,sa),(ads,adm),(es,ed);
 insert into public.admin_profiles(id,display_name,role) values(sa,'CMS TEST SA','SUPERADMIN'),(adm,'CMS TEST ADMIN','ADMIN'),(ed,'CMS TEST EDITOR','EDITOR');
 if (select count(*) from public.cms_documents where module_id in ('cities','institutions','careers') and draft->>'_kind' is not null)<>69 then raise exception 'Approved catalog import count changed'; end if; checks:=checks+1;
 if exists(select 1 from public.cms_versions where origin='import' and created_by is not null) then raise exception 'Import fabricated a human actor'; end if; checks:=checks+1;
 perform set_config('request.jwt.claims','{}',true); set local role anon;
 if jsonb_array_length(public.cms_public_entries())<>69 then raise exception 'Public published catalog unavailable'; end if; checks:=checks+1;
 begin perform public.cms_editorial_bundle('save','[]');raise exception 'Anonymous mutation accepted';exception when insufficient_privilege then checks:=checks+1;end;
 begin perform count(*) from public.cms_documents;raise exception 'Anonymous draft access';exception when insufficient_privilege then checks:=checks+1;end;
 reset role;
 select * into d from public.cms_documents where entity_key='sede/universidad-siglo-21-concepcion';
 select count(*) into initial_versions from public.cms_versions where document_id=d.id;
 original:=d.draft;payload:=jsonb_set(d.draft,'{data,phone}','"TEST PHONE"');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ed,'role','authenticated','session_id',es)::text,true);set local role authenticated;
 perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision,'payload',payload)));
 if public.cms_read_published(d.module_id,d.entity_key)->'data' ? 'phone' then raise exception 'Phone draft leaked';end if;checks:=checks+1;
 begin perform public.cms_editorial_bundle('publish',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision+1,'payload',payload)));raise exception 'Editor published';exception when insufficient_privilege then checks:=checks+1;end;
 begin perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision,'payload',payload)));raise exception 'Revision conflict ignored';exception when serialization_failure then checks:=checks+1;end;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',adm,'role','authenticated','session_id',ads)::text,true);set local role authenticated;
 perform public.cms_editorial_bundle('publish',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision+1,'payload',payload)));
 if public.cms_read_published(d.module_id,d.entity_key)->'data'->>'phone'<>'TEST PHONE' then raise exception 'Phone publication failed';end if;checks:=checks+1;
 if (select count(*) from public.cms_versions where document_id=d.id)<>initial_versions+1 then raise exception 'Snapshot missing';end if;checks:=checks+1;
 begin perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision+2,'payload',payload),jsonb_build_object('id',d.id,'revision',d.revision+2,'payload',payload)));raise exception 'Duplicate part accepted';exception when invalid_parameter_value then checks:=checks+1;end;
 reset role;
 select * into master from public.cms_documents where entity_key='carrera/abogacia';select * into offer from public.cms_documents where entity_key='oferta/'||(select draft->'data'->>'id' from public.cms_documents where draft->>'_kind'='offering' and draft->'data'->>'careerId'='abogacia' limit 1);
 payload:=jsonb_set(master.draft,'{data,description}','"TEST ABOGACIA"');
 set local role authenticated;
 perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',master.id,'revision',master.revision,'payload',payload),jsonb_build_object('id',offer.id,'revision',offer.revision,'payload',offer.draft)));
 if public.cms_read_published('careers','carrera/abogacia')->'data'->>'description'='TEST ABOGACIA' then raise exception 'Career draft leaked';end if;checks:=checks+1;
 perform public.cms_editorial_bundle('publish',jsonb_build_array(jsonb_build_object('id',master.id,'revision',master.revision+1,'payload',payload),jsonb_build_object('id',offer.id,'revision',offer.revision,'payload',offer.draft)));
 if public.cms_read_published('careers','carrera/abogacia')->'data'->>'description'<>'TEST ABOGACIA' then raise exception 'Career publication failed';end if;checks:=checks+1;
 reset role;
 select * into city from public.cms_documents where entity_key='concepcion';original:=city.draft;payload:=jsonb_set(original,'{data,heroTitle}','"TEST CONCEPCION"');set local role authenticated;
 perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',city.id,'revision',city.revision,'payload',payload)));
 if public.cms_read_published('cities','concepcion')->'data' ? 'heroTitle' then raise exception 'City draft leaked';end if;checks:=checks+1;
 perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',city.id,'revision',city.revision+1,'payload',original)));
 if (select draft from public.cms_documents where id=city.id)<>original then raise exception 'Discard/reset failed';end if;checks:=checks+1;
 -- Duplicate offering and missing relationships cannot use the older single-document RPC to bypass integrity.
 result:=public.cms_mutate_content('create',p_module=>'careers',p_entity=>'oferta/'||gen_random_uuid(),p_payload=>jsonb_set(offer.draft,'{data,id}',to_jsonb(gen_random_uuid()::text)));fixture:=(result->'document'->>'id')::uuid;
 begin perform public.cms_mutate_content('publish',p_id=>fixture,p_revision=>1);raise exception 'Duplicate offering published';exception when unique_violation then checks:=checks+1;end;
 result:=public.cms_mutate_content('create',p_module=>'careers',p_entity=>'oferta/'||gen_random_uuid(),p_payload=>jsonb_set(jsonb_set(offer.draft,'{data,id}',to_jsonb(gen_random_uuid()::text)),'{data,careerId}','"missing-master"'));fixture:=(result->'document'->>'id')::uuid;
 begin perform public.cms_mutate_content('publish',p_id=>fixture,p_revision=>1);raise exception 'Broken relation published';exception when check_violation then checks:=checks+1;end;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',sa,'role','authenticated','session_id',ss)::text,true);set local role authenticated;
 select id into fixture from public.cms_documents where module_id='design' and entity_key='main';
 reset role;select * into design_doc from public.cms_documents where id=fixture;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ed,'role','authenticated','session_id',es)::text,true);set local role authenticated;
 begin perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',design_doc.id,'revision',design_doc.revision,'payload',design_doc.draft)));raise exception 'Unchanged restricted document exposed';exception when insufficient_privilege then checks:=checks+1;end;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',adm,'role','authenticated','session_id',ads)::text,true);set local role authenticated;
 if cms_private.media_published(media) then raise exception 'Unpublished media exposed';end if;checks:=checks+1;
 select * into d from public.cms_documents where entity_key='sede/universidad-siglo-21-concepcion';payload:=jsonb_set(d.draft,'{data,image}',to_jsonb('/media/cms/'||media));
 perform public.cms_editorial_bundle('save',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision,'payload',payload)));
 if cms_private.media_published(media) then raise exception 'Draft media exposed';end if;checks:=checks+1;
 perform public.cms_editorial_bundle('publish',jsonb_build_array(jsonb_build_object('id',d.id,'revision',d.revision+1,'payload',payload)));
 if not cms_private.media_published(media) then raise exception 'Published media unavailable';end if;checks:=checks+1;
 begin perform public.cms_mutate_content('save',p_id=>d.id,p_revision=>d.revision+2,p_payload=>d.draft#-'{data,gallery}');raise exception 'Missing gallery accepted';exception when invalid_parameter_value then checks:=checks+1;end;
 begin perform public.cms_mutate_content('save',p_id=>master.id,p_revision=>master.revision+2,p_payload=>master.draft#-'{data,studyPlan}');raise exception 'Missing plan accepted';exception when invalid_parameter_value then checks:=checks+1;end;
 reset role;
 perform set_config('request.jwt.claims','{}',true);set local role anon;
 if public.cms_read_published('institutions','sede/universidad-siglo-21-concepcion')->'data'->>'phone'<>'TEST PHONE' then raise exception 'Public reader did not update';end if;checks:=checks+1;
 reset role;
 perform set_config('cms.tests.macro3',jsonb_build_object('checks',checks,'passed',true,'fixtures','rolled back')::text,true);
end; $$;
select current_setting('cms.tests.macro3')::jsonb as result;
rollback;
